import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int t = Integer.parseInt(st.nextToken()); while (t-- > 0) { int n = Integer.parseInt(br.readLine()); st = new StringTokenizer(br.readLine()); long sum = 0; for (int i = 1; i <= n; i++) { sum += Long.parseLong(st.nextToken()); } if (sum >= 0) { System.out.println("YES"); } else { System.out.println("NO"); } } } }